const PORT = 3000;
const PROD = process.env.NODE_ENV === "production";
const TEST = process.env.MFA_TEST_MODE === "true" || !PROD;
const ACCOUNT = { id: "account-marcus", email: "marcus@example.com", password: "BankDemo!9" };
